Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='verifyconsumer', at=datetime(2026, 10, 22, 0, 0, 0), actor='assistant', title='Read every reader before deleting or changing what it reads', body='Before deleting a field, route, file or function, find every consumer with grep across app, web and android (the APK is a client of the act routes), and read each one. A consumer that is not found is assumed to exist until the search names where it would be.', rationale='Removing a field once silently broke a consumer no search had listed.', supersedes=()))